    private void FindPath_Click(object sender,RoutedEventArgs e){if(Site is not{ } site||RelationshipDeviceBox.SelectedItem is not Device target){MessageBox.Show("Select a target device.");return;}var start=PathStartBox.Text.Trim();if(string.IsNullOrWhiteSpace(start)){MessageBox.Show("Enter a starting point.");return;}var tokens=UnavailableNodesBox.Text.Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries);var excludedNodes=new HashSet<string>(tokens.Where(x=>!x.StartsWith('#')),StringComparer.OrdinalIgnoreCase);var excludedHops=new HashSet<long>(tokens.Where(x=>x.StartsWith('#')).Select(x=>long.TryParse(x[1..],out var id)?id:0).Where(x=>x>0));var paths=_pathfinder.Find(_db.Relationships(site.Id),start,target.Name,excludedHops,excludedNodes);PathResultsList.ItemsSource=paths;if(paths.Count==0)MessageBox.Show(this,"No supported access path was found with the current exclusions.","Access paths");}
