    private void ApplyTopologyZoom(){TopologyScale.ScaleX=TopologyScale.ScaleY=_topologyZoom;}
    private void RenderTopology()
    {
        TopologyCanvas.Children.Clear();if(Site is not{ } site||TopologyRootBox.SelectedItem is not Device root){TopologySummaryText.Text="Select a site and starting firewall.";return;}var target=TopologyTargetBox.SelectedItem as Device;var map=_topology.Build(site.Id,root.Id,target?.Id,TopologyOnlyPathCheck.IsChecked==true);TopologySummaryText.Text=map.Summary;TopologyCanvas.Width=map.Width;TopologyCanvas.Height=map.Height;var nodes=map.Nodes.ToDictionary(x=>x.Device.Id);
        if(map.Nodes.Count==0){var empty=new TextBlock{Text=map.Summary,Foreground=Brush("#91A0B6"),FontSize=15,TextWrapping=TextWrapping.Wrap,Width=480};Canvas.SetLeft(empty,36);Canvas.SetTop(empty,40);TopologyCanvas.Children.Add(empty);return;}
        foreach(var edge in map.Edges)
        {
            if(!nodes.TryGetValue(edge.FromDeviceId,out var from)||!nodes.TryGetValue(edge.ToDeviceId,out var to))continue;var x1=from.X+103;var y1=from.Y+41;var x2=to.X+103;var y2=to.Y+41;var line=new System.Windows.Shapes.Line{X1=x1,Y1=y1,X2=x2,Y2=y2,Stroke=edge.IsOnSelectedPath?Brush("#4F8CFF"):Brush("#40516C"),StrokeThickness=edge.IsOnSelectedPath?3:1.5,ToolTip=$"{edge.RelationshipType.Replace('_',' ')}\nSource: {edge.Source}\nConfidence: {edge.Confidence:P0}\nStatus: {edge.Status}"};TopologyCanvas.Children.Add(line);var marker=new System.Windows.Shapes.Ellipse{Width=7,Height=7,Fill=edge.IsOnSelectedPath?Brush("#76A7FF"):Brush("#60738F"),IsHitTestVisible=false};Canvas.SetLeft(marker,x2-3.5);Canvas.SetTop(marker,y2-3.5);TopologyCanvas.Children.Add(marker);
            if(edge.IsOnSelectedPath||edge.RelationshipType!="CONNECTED_TO"){var label=new Border{Background=Brush("#111C2D"),BorderBrush=Brush("#2B3B53"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(4),Padding=new Thickness(5,2,5,2),Child=new TextBlock{Text=edge.RelationshipType.Replace("_TO","").Replace('_',' '),Foreground=Brush("#91A0B6"),FontSize=9},IsHitTestVisible=false};Canvas.SetLeft(label,(x1+x2)/2-30);Canvas.SetTop(label,(y1+y2)/2-12);Panel.SetZIndex(label,1);TopologyCanvas.Children.Add(label);}
        }
        foreach(var node in map.Nodes)
        {
            var border=new Border{Width=206,Height=82,CornerRadius=new CornerRadius(9),Background=NodeBrush(node.Device.DeviceType),BorderBrush=node.IsRoot?Brush("#FFB74D"):node.IsTarget?Brush("#72E0C0"):node.IsOnSelectedPath?Brush("#4F8CFF"):Brush("#34445E"),BorderThickness=new Thickness(node.IsRoot||node.IsTarget?2.5:1.2),Padding=new Thickness(11,8,11,7),Cursor=System.Windows.Input.Cursors.Hand,ToolTip=$"{node.Device.Name}\nIP: {node.Device.IpAddress??"Not documented"}\nType: {node.Device.DeviceType??"Unknown"}\nZone: {node.Device.Zone??"Unknown"}"};var stack=new StackPanel();stack.Children.Add(new TextBlock{Text=(node.IsRoot?"◆ ":node.IsTarget?"● ":"")+node.Device.Name,FontWeight=FontWeights.SemiBold,FontSize=13,Foreground=Brush("#F2F6FC"),TextTrimming=TextTrimming.CharacterEllipsis});stack.Children.Add(new TextBlock{Text=node.Device.IpAddress??"IP not documented",Foreground=string.IsNullOrWhiteSpace(node.Device.IpAddress)?Brush("#718096"):Brush("#76A7FF"),FontFamily=new FontFamily("Cascadia Mono, Consolas"),FontSize=12,Margin=new Thickness(0,4,0,0)});stack.Children.Add(new TextBlock{Text=$"{node.Device.DeviceType??"Unknown type"}  ·  {node.Device.Zone??"No zone"}",Foreground=Brush("#91A0B6"),FontSize=10,Margin=new Thickness(0,3,0,0),TextTrimming=TextTrimming.CharacterEllipsis});border.Child=stack;border.MouseLeftButtonUp+=(_,_)=>{TopologyTargetBox.SelectedItem=_siteDevices.FirstOrDefault(x=>x.Id==node.Device.Id);RenderTopology();};Canvas.SetLeft(border,node.X);Canvas.SetTop(border,node.Y);Panel.SetZIndex(border,2);TopologyCanvas.Children.Add(border);
        }
        ApplyTopologyZoom();
    }
    private static Brush NodeBrush(string? type)=>type?.ToLowerInvariant() switch{"firewall"=>Brush("#40252D"),"router"=>Brush("#40331E"),"switch"=>Brush("#173659"),"hypervisor host"=>Brush("#153B36"),"server"=>Brush("#302650"),"virtual machine"=>Brush("#29284A"),_=>Brush("#182337")};
    private static Brush Brush(string color)=>new SolidColorBrush((Color)ColorConverter.ConvertFromString(color));
    private void AnalyzeTrouble_Click(object sender,RoutedEventArgs e)
    {
        if(Site is not{ } site){MessageBox.Show(this,"Select a site first.","Troubleshoot");return;}try{_relationshipInference.Infer(site.Id);var report=TroubleReportBox.Text.Trim();var plan=_troubleshooter.Analyze(site.Id,report,(TroubleTargetBox.SelectedItem as Device)?.Id);_activeTroubleSessionId=_db.SaveTroubleshootingPlan(site.Id,report,plan);TroubleSummaryText.Text=plan.Summary;TroubleStepsGrid.ItemsSource=_db.TroubleshootingSteps(_activeTroubleSessionId.Value);if(plan.Target is not null){TroubleTargetBox.SelectedItem=_siteDevices.FirstOrDefault(x=>x.Id==plan.Target.Id);_troubleUnavailableRelationships.Clear();RefreshTroubleTraversal(site,plan.Target);}TroubleSessionsGrid.ItemsSource=_db.TroubleshootingSessions(site.Id);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Troubleshoot",MessageBoxButton.OK,MessageBoxImage.Information);}
    }
