    private void RefreshTroubleTraversal(Site site,Device target){var trace=_traversal.Trace(site.Id,target.Id);TroubleTraversalGrid.ItemsSource=trace;var conflicts=trace.Count(x=>x.Status=="conflicting");TraversalSummaryText.Text=trace.Count==0?$"No device-to-host or device-to-network relationships are stored for {target.Name}. Re-import the source workbook or define relationships manually.":$"Trace outward from {target.Name}: {trace.Count} documented hop(s) across host, switch, subnet, VLAN and dependency boundaries"+(conflicts>0?$"; {conflicts} conflicting hop(s) require review.":".");var paths=_pathfinder.Find(_db.Relationships(site.Id),"Current workstation",target.Name,_troubleUnavailableRelationships);TraversalAccessPathText.Text=paths.Count==0?"No complete Current workstation → target access path is documented. The table still shows the diagnostic trace outward from the device.":string.Join("\n",paths.Take(2).Select(x=>x.Display.Split('\n')[0]));}
