    private void MergeSite_Click(object sender,RoutedEventArgs e)
    {
        if(Site is not { } source||Company is null){MessageBox.Show("Select the duplicate/source site first.");return;}var targets=_db.Sites(Company.Id).Where(x=>x.Id!=source.Id).ToList();var dialog=new MergeSiteDialog(source,targets){Owner=this};if(dialog.ShowDialog()!=true||dialog.Target is null)return;
        if(MessageBox.Show(this,$"Merge '{source.Name}' into '{dialog.Target.Name}'? This cannot be undone.","Confirm site merge",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;
        try{_db.MergeSites(source.Id,dialog.Target.Id);ReloadSites(dialog.Target.Id);}catch(Exception ex){MessageBox.Show(this,$"The sites could not be merged. No partial changes were saved.\n\n{ex.Message}","Merge site",MessageBoxButton.OK,MessageBoxImage.Error);}
    }
