    private void DeleteDevice_Click(object sender,RoutedEventArgs e){if(DevicesGrid.SelectedItem is not Device device){MessageBox.Show("Select a device first.");return;}if(MessageBox.Show(this,$"Delete device '{device.Name}' and its related facts, interfaces and topology relationships?","Confirm",MessageBoxButton.YesNo,MessageBoxImage.Warning)==MessageBoxResult.Yes){_db.DeleteDevice(device.Id);RefreshSite();}}
    private void AddNetwork_Click(object sender,RoutedEventArgs e){if(Site is not{ } site)return;var d=new NetworkDialog(){Owner=this};if(d.ShowDialog()==true){try{_db.AddNetwork(site.Id,d.NetworkName,d.Cidr,d.VlanId,d.Zone);RefreshSite();}catch(Exception ex){MessageBox.Show(this,$"Could not add network.\n\n{ex.Message}");}}}
    private void EditNetwork_Click(object sender,RoutedEventArgs e){if(NetworksGrid.SelectedItem is not NetworkRecord network){MessageBox.Show("Select a network first.");return;}var d=new NetworkDialog(network){Owner=this};if(d.ShowDialog()==true){try{_db.UpdateNetwork(new NetworkRecord(network.Id,network.SiteId,d.NetworkName,d.Cidr,d.VlanId,d.Zone));RefreshSite();}catch(Exception ex){MessageBox.Show(this,$"Could not update network.\n\n{ex.Message}");}}}
    private void DeleteNetwork_Click(object sender,RoutedEventArgs e){if(NetworksGrid.SelectedItem is not NetworkRecord network){MessageBox.Show("Select a network first.");return;}if(MessageBox.Show(this,$"Delete network '{network.Name}' ({network.Cidr})?","Confirm",MessageBoxButton.YesNo,MessageBoxImage.Warning)==MessageBoxResult.Yes){_db.DeleteNetwork(network.Id);RefreshSite();}}
    private void Upload_Click(object sender,RoutedEventArgs e)
    {
        if(Company is null){MessageBox.Show("Select or create the destination company first.");return;} var dialog=new OpenFileDialog{Filter="Supported files (*.csv;*.xlsx;*.vsdx)|*.csv;*.xlsx;*.vsdx|Visio (*.vsdx)|*.vsdx|CSV (*.csv)|*.csv|Excel (*.xlsx)|*.xlsx"}; if(dialog.ShowDialog()!=true)return;
        try
        {
            _pendingPath=dialog.FileName; _preview=[]; _visioPreview=[];
            if(_visioReader.Supports(dialog.FileName))
            {
                _visioPreview=_visioReader.Read(dialog.FileName).Proposals.ToList(); _visioImports.ClassifyForCompany(Company.Id,_visioPreview); PreviewGrid.ItemsSource=_visioPreview; ImportButton.IsEnabled=_visioPreview.Any(x=>x.Import);
                ImportStatus.Text=$"{_visioPreview.Count} proposal(s): {_visioPreview.Count(x=>x.Import)} selected; {_visioPreview.Count(x=>x.Status=="Unresolved site")} need a site mapping.";
            }
            else
            {
                _preview=_reader.Read(dialog.FileName).ToList(); if(_preview.Any(x=>!string.IsNullOrWhiteSpace(x.SiteLocation)))_imports.ClassifyForCompany(Company.Id,_preview); else if(Site is not null)_imports.Classify(Site.Id,_preview); else throw new InvalidDataException("The file has no Site Location column. Select a site before importing it."); PreviewGrid.ItemsSource=_preview; ImportButton.IsEnabled=_preview.Count>0; ImportStatus.Text=$"{_preview.Count} row(s) ready across {_preview.Select(x=>x.SiteLocation).Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).Count()} site(s).";
            }
            Tabs.SelectedIndex=3;
        }
        catch(Exception ex){MessageBox.Show(this,$"The file could not be read.\n\n{ex.Message}","Import",MessageBoxButton.OK,MessageBoxImage.Error);}
    }
    private void Import_Click(object sender,RoutedEventArgs e)
    {
        if(Company is null||_pendingPath is null)return;
        try
        {
            if(_visioPreview.Count>0){var touched=_visioImports.ImportForCompany(Company.Id,_pendingPath,_visioPreview);ReloadSites(Site?.Id??touched.FirstOrDefault()?.Id);}
            else {var siteAware=_preview.Any(x=>!string.IsNullOrWhiteSpace(x.SiteLocation));if(siteAware){var touched=_imports.ImportForCompany(Company.Id,_pendingPath,_preview);ReloadSites(Site?.Id??touched.FirstOrDefault()?.Id);}else if(Site is not null)_imports.Import(Site.Id,_pendingPath,_preview);else throw new InvalidOperationException("Select a site for this file.");}
            _preview=[];_visioPreview=[];_pendingPath=null;PreviewGrid.ItemsSource=null;ImportButton.IsEnabled=false;ImportStatus.Text="Import complete.";RefreshSite();
        }
        catch(Exception ex){MessageBox.Show(this,$"Import failed.\n\n{ex.Message}","Import",MessageBoxButton.OK,MessageBoxImage.Error);}
    }
    private Conflict? SelectedConflict()=>ConflictsGrid.SelectedItem as Conflict;
    private void Resolve(Resolution resolution,string? manual=null) { var c=SelectedConflict();if(c is null||c.Status!="unresolved"){MessageBox.Show("Select an unresolved conflict first.");return;}if(resolution==Resolution.Manual&&string.IsNullOrWhiteSpace(manual)){MessageBox.Show("Enter the correct value first.");return;}_imports.Resolve(c,resolution,manual);RefreshSite(); }
    private void Keep_Click(object sender,RoutedEventArgs e)=>Resolve(Resolution.KeepExisting);
    private void Accept_Click(object sender,RoutedEventArgs e)=>Resolve(Resolution.AcceptNew);
    private void Manual_Click(object sender,RoutedEventArgs e)=>Resolve(Resolution.Manual,ManualValue.Text.Trim());
    private void Separate_Click(object sender,RoutedEventArgs e)=>Resolve(Resolution.SeparateDevice);
}
